            if (correct.length !== user.length || !correct.every((val, idx) => val === user[idx])) {
                allCorrect = false;
                break;
            }
        }

        return allCorrect;
    }

    handleSubmit(e) {
        e.preventDefault();

        const userAnswers = this.getSelectedAnswers();
        const hasAnswered = Object.values(userAnswers).some(arr => arr.length > 0);

        if (!hasAnswered) {
            this.showMessage('Please select at least one answer per question', 'error');
            return;
        }

        const isCorrect = this.validateAnswers(userAnswers);

        if (isCorrect) {
            this.showMessage('🎉 Perfect! All your answers are correct!', 'success');
